const files = JSON.parse(gunzipSync(Buffer.from(payload, 'base64')).toString('utf8'));
const target = resolve(process.argv[2] || 'hosted');
try { await lstat(target); throw new Error('Output directory already exists: ' + target); } catch (error) { if (error.code !== 'ENOENT') throw error; }
for (const [name, content] of Object.entries(files)) {
  if (isAbsolute(name) || name.split('/').includes('..')) throw new Error('Unsafe path');
  const output = resolve(target, name);
  await mkdir(dirname(output), { recursive: true });
  await writeFile(output, content, { flag: 'wx' });
}
console.log(`Extracted ${Object.keys(files).length} files to ${target}`);
